import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/79-警惕“确认偏误”.md","filePath":"books/xuehui-tiwen/79-警惕“确认偏误”.md","lastUpdated":1794316978000}'),n={name:"books/xuehui-tiwen/79-警惕“确认偏误”.md"};function i(_,a,d,c,l,p){return o(),r("div",null,[...a[0]||(a[0]=[e("h2",{id:"警惕-确认偏误",tabindex:"-1"},[s("警惕“确认偏误” "),e("a",{class:"header-anchor",href:"#警惕-确认偏误","aria-label":'Permalink to "警惕“确认偏误”"'},"​")],-1),e("p",null,"当我们试图理解为什么人们会以某种方式行事时，不同的视角或观点往往会影响我们选择何种原因加以考虑。我们选择去寻找的事物会影响我们能够看到的事物。我们熟悉的视角越多，在找到可能的替代原因方面就会越有创造力。例如，社会学家、社会工作者、心理学家、心理医生、生物学家、神经科学家、营养学家、环境主义者、警察、共和党人和民主党人，以及商人，他们在思考各种可能的原因时，可能会青睐不同类型的原因。你越能尽快熟悉多种不同的视角，就越能找到事件可能的替代原因。当你在作业中遇到各种不同的视角时，一定要努力让自己尽快熟悉各种可能的原因。同时，在你努力找到各种原因时，要警惕专家和你都具有的一个倾向——沉浸在“确认偏误”（confirmation bias）当中，只努力寻找并依赖和我们的信念相一致的证据。",-1)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
